/**
 * A revision's zone sub-packet reader: one record off `c`, by the ordinal that
 * leads it. 1 decoded into `out`; 2 read, with no canonical arm (the walk steps
 * past it); 0 unreadable, which ends the walk -- records carry no length, so
 * nothing after one can be found; -1 nothing left.
 */
typedef int (*ProtoZoneSubFn)(RsprotBuf* c, struct PktZoneSubPacket* out);

/** A zone sub-packet sent on its own (`follows` mode) into its top-level arm. */
void
proto_adapt_zone_to_packet(struct PktZoneSubPacket const* sub, struct RevPacket* out);

